<script setup>
import ReadToolbar from './ReadToolbar.vue';
import {useChecklistRoleDrag} from './checklist-role-drag.js';
import {freshnessTip} from './checklist-freshness.js';
import {isTaskComplete} from './checklist-status.js';
import {ref,computed,onMounted,onUnmounted,watch} from 'vue';
import {backgroundRead} from './background-read.js';
import TaskSettingSnapshots from './TaskSettingSnapshots.vue';
import ChecklistGroups from './ChecklistGroups.vue';
import {groupChecklistRows} from './checklist-groups.js';
import ChecklistOverview from './ChecklistOverview.vue';
const data=ref({roles:[]}),period=ref('overview'),roleKey=ref(''),settings=ref(false),busy=ref(false),message=ref(''),filter=ref('all'),roleSearch=ref(''),groupEditing=ref(false),snapshotsOpen=ref(false);
const readResults=ref([]),readDetails=ref(false),windows=ref([]),windowKey=ref(''),windowLoading=ref(false),windowError=ref('');
const readSummary=computed(()=>{const rows=readResults.value,failed=rows.filter(x=>x.error).length,missing=rows.filter(x=>!x.error&&x.missing>0).length;return `读取完成 · 成功 ${rows.length-failed} 个窗口`+(failed?` · 失败 ${failed} 个`:'')+(missing?` · ${missing} 个窗口有未加载数据`:'')});
async function loadWindows(){windowLoading.value=true;windowError.value='';try{windows.value=await call('windows');if(!windows.value.some(w=>w.id===windowKey.value))windowKey.value=windows.value[0]?.id||''}catch(e){windowError.value=e.message}finally{windowLoading.value=false}}
const taskScroller=ref(null);
watch([roleKey,period],()=>requestAnimationFrame(()=>{if(taskScroller.value)taskScroller.value.scrollTop=0}));
const labels={unknown:'未知',todo:'未完成',done:'已完成',claimable:'待领取',active:'进行中',fostering:'寄养中',home:'待寄养',card_running:'生效中',card_expired:'待换卡',cooldown:'冷却中',occupied:'已有徒弟',ready:'冷却结束',inactive:'暂无记录',progressing:'积累中',target_met:'已达标',unavailable:'未开放'};
const manualStates=['unknown','todo','done','claimable','active'];
const isDone=isTaskComplete;
const reminds=t=>t.priority!=='muted'&&t.available!==false;
const role=computed(()=>data.value.roles.find(r=>r.key===roleKey.value));
const visibleRoles=computed(()=>data.value.roles.filter(r=>!roleSearch.value||(r.name+' '+r.server).includes(roleSearch.value)));
const drag=useChecklistRoleDrag(groupAction);
async function moveGroupKey(event,id){
 if(!event.altKey||!['ArrowUp','ArrowDown'].includes(event.key))return;
 event.preventDefault();event.stopPropagation();
 if(drag.saving.value)return;
 const groups=data.value.groups||[],index=groups.findIndex(group=>group.id===id),down=event.key==='ArrowDown',target=groups[index+(down?1:-1)];
 if(index<0||!target)return;
 drag.saving.value=true;
 try{await (groupAction)({action:'group_move',id,before:target.id,after:down})}
 finally{drag.saving.value=false}
}
const roleGroups=computed(()=>groupChecklistRows(data.value.groups,visibleRoles.value,r=>r,true));
async function groupAction(payload){message.value='';try{data.value=await call('groups',payload);if(!data.value.roles.some(r=>r.key===roleKey.value))roleKey.value=data.value.roles[0]?.key||'';return true}catch(e){message.value=e.message;return false}}
const tasks=computed(()=>role.value?.tasks.filter(t=>t.period===period.value&&(settings.value||t.enabled))||[]);
const monitored=computed(()=>tasks.value.filter(t=>t.enabled&&!t.monitor&&reminds(t)));
const done=computed(()=>monitored.value.filter(isDone).length);
const summary=computed(()=>[
 {label:'待处理',count:monitored.value.filter(t=>!isDone(t)&&t.status!=='unknown').length,tone:'pending'},
 {label:'未知',count:monitored.value.filter(t=>t.status==='unknown').length,tone:'muted'},
 {label:'计时提醒',count:tasks.value.filter(t=>t.enabled&&reminds(t)&&t.monitor&&t.id!=='mentoring_points').length,tone:'muted'}
,{label:'上周储存',count:tasks.value.filter(t=>t.enabled&&t.priority!=='muted'&&t.storage?.remaining>0).length,tone:'pending'}
].filter(x=>x.count));
const shopRank=t=>['勋章商店','荣誉商店','寮商店','神龛','千物宝库','契灵商店','寄售屋'].indexOf(t.name.split(' · ')[0]);
const priorityRank=t=>t.priority==='important'?0:t.priority==='muted'?2:1;
const compareShop=(a,b)=>shopRank(a)-shopRank(b)||priorityRank(a)-priorityRank(b)||({411:0,490001:1,434111:2}[a.icon]??3)-({411:0,490001:1,434111:2}[b.icon]??3);
const dailyRank=t=>t.id==='evening_boss'?8.5:Number(t.id.slice(1));
function category(t){if(t.category==='guild')return '阴阳寮活动';if(t.category==='mentoring')return '师徒任务';if(t.category==='shop')return '每周兑换';if(t.monitor)return '定时提醒';if(t.lifetime)return '累计福利';if(period.value==='daily')return ['d0','d1','d2','d3'].includes(t.id)?'每日事务':'挑战与资源';return ['w0','w1','w2','w6','w7','w8'].includes(t.id)?'福利与分享':'每周挑战'}
const groups=computed(()=>{const map=new Map();for(const t of tasks.value){if(!settings.value&&filter.value==='pending'&&((isDone(t)&&!(t.storage?.remaining>0))||!reminds(t)))continue;const name=category(t);if(!map.has(name))map.set(name,[]);map.get(name).push(t)}const order=period.value==='daily'?['每日事务','挑战与资源','阴阳寮活动','师徒任务','定时提醒']:['福利与分享','每周挑战','阴阳寮活动','每周兑换','累计福利'];return [...map].map(([name,items])=>({name,items:name==='每周兑换'?items.sort(compareShop):name==='师徒任务'?items.sort((a,b)=>['mentoring_practice','mentoring_points','mentoring_recruit'].indexOf(a.id)-['mentoring_practice','mentoring_points','mentoring_recruit'].indexOf(b.id)):name==='挑战与资源'?items.sort((a,b)=>dailyRank(a)-dailyRank(b)):items})).map(g=>({...g,items:[...g.items].sort((a,b)=>g.name==='每周兑换'?compareShop(a,b):priorityRank(a)-priorityRank(b))})).sort((a,b)=>order.indexOf(a.name)-order.indexOf(b.name))});
function roleProgress(r){const ts=r.tasks.filter(t=>t.enabled&&!t.monitor&&reminds(t)&&t.period===period.value);return ts.filter(isDone).length+' / '+ts.length}
function prayerName(t){const names=[...new Set((t.parts||[]).map(p=>p.hero_name).filter(Boolean))];return names.length===1?names[0]:''}
const sourceTip=freshnessTip;
async function call(action,payload={}){const r=await window.pywebview.api.task_checklist(action,payload);if(!r.ok)throw Error(r.error);return r.data}
async function load(){try{data.value=await call('load');if(!role.value)roleKey.value=data.value.roles[0]?.key||''}catch(e){message.value=e.message}}
async function change(task,payload){try{await call('set',{role:roleKey.value,task:task.id,...payload});await load()}catch(e){message.value=e.message}}
async function read(target='all',chosenRole=''){if(busy.value)return;busy.value=true;message.value='';readResults.value=[];readDetails.value=false;try{const r=await backgroundRead('checklist',chosenRole?{role:chosenRole}:{target});readResults.value=r.results||[];await load()}catch(e){message.value=e.message}finally{busy.value=false}}
function openRole(key,tab='daily'){roleKey.value=key;period.value=tab;settings.value=false}
async function toggleAll(enabled){for(const t of tasks.value)await change(t,{enabled})}
async function refreshReadControls(){await loadWindows();await load();if(windowError.value)message.value=windowError.value}
let monitorTimer;onMounted(()=>{refreshReadControls();monitorTimer=setInterval(()=>{if(!busy.value)load()},15000)});onUnmounted(()=>clearInterval(monitorTimer));
</script>
<template>
<div class="checklist workspace-page">
 <header class="workspace-header"><div><h1>日常清单</h1><p>每日与每周安排，一眼看清还剩什么</p></div><ReadToolbar :windows="windows" v-model="windowKey" :busy="busy||windowLoading" @refresh="refreshReadControls" @read="read($event)" @all="read('all')"><template #current><button v-if="period!=='overview'" :disabled="busy||!role" @click="read('all',roleKey)">读取当前角色</button></template></ReadToolbar></header>

 <div class="bar"><div class="tabs workspace-view-switch"><button :class="{chosen:period==='overview'}" :aria-pressed="period==='overview'" @click="period='overview'">全部角色</button><button :class="{chosen:period==='daily'}" :aria-pressed="period==='daily'" @click="period='daily'">每日任务</button><button :class="{chosen:period==='weekly'}" :aria-pressed="period==='weekly'" @click="period='weekly'">每周任务</button></div><button class="group-manager-toggle" :aria-pressed="groupEditing" @click="groupEditing=!groupEditing">{{groupEditing?'收起分组管理':'分组管理'}}</button><span class="period-label">{{period==='weekly'?data.week:data.day}}{{period==='weekly'?' 起的一周':''}}</span></div>
 <TaskSettingSnapshots v-if="snapshotsOpen&&role" :source="role" :roles="data.roles" :snapshots="data.snapshots||[]" :groups="data.groups||[{id:'',name:'未分组'}]" @updated="data=$event" @close="snapshotsOpen=false"/>
 <p v-if="message" class="notice" role="status">{{message}}</p>
 <div v-if="readResults.length" class="read-feedback"><div class="read-feedback-summary"><span role="status">{{readSummary}}</span><button :aria-expanded="readDetails" @click="readDetails=!readDetails">{{readDetails?'收起详情':'查看详情'}}</button><button aria-label="关闭读取结果" @click="readResults=[]">×</button></div><div v-if="readDetails" class="read-feedback-details"><p class="read-feedback-hint">未加载的数据保留原记录。</p><div v-for="(result,index) in readResults" :key="index" class="read-result"><strong>{{result.title}}</strong><span>{{result.error||('获得 '+result.count+' 项有效状态'+(result.missing?' · '+result.missing+' 项未加载':''))}}</span><p v-if="result.warning">{{result.warning}}</p></div></div></div>
 <ChecklistGroups v-if="groupEditing" :busy="drag.saving.value" :roles="data.roles" :archived-roles="data.archived_roles||[]" :groups="data.groups||[{id:'',name:'未分组'}]" @action="groupAction" @close="groupEditing=false"/>
 <ChecklistOverview v-if="period==='overview'" :roles="data.roles" :groups="data.groups" :busy="busy" :group-action="groupAction" @open="openRole" @read="read('all',$event)"/>
 <div v-else class="layout"><aside class="role-nav"><div class="role-nav-head"><span>角色</span><small>{{data.roles.length}} 位</small></div><input class="role-search" aria-label="搜索清单角色" placeholder="搜索角色 / 区服" v-model="roleSearch"><div class="role-scroll" @click.capture="drag.click($event)" :aria-busy="drag.saving.value"><section v-for="g in roleGroups" :key="g.id" class="nav-role-group"><button v-if="g.showHeader" class="nav-group-toggle" @keydown="moveGroupKey($event,g.id)" :data-checklist-group="g.id" draggable="true" @dragstart="drag.startGroup($event,g.id)" @dragend="drag.clear" title="拖动分组标题调整顺序，或按 Alt + ↑ / ↓ 移动分组" :class="{'drag-group-target':drag.hoverGroup.value===g.id,'role-dragging':drag.groupDragged.value===g.id,'role-drop-before':drag.groupHovered.value===g.id&&!drag.groupAfter.value,'role-drop-after':drag.groupHovered.value===g.id&&drag.groupAfter.value}" @dragover="drag.overGroup($event,g.id)" @drop="drag.drop($event,g.id)" :aria-expanded="!!roleSearch||!g.collapsed" @click="groupAction({action:'toggle',id:g.id,collapsed:!g.collapsed})"><span>{{roleSearch||!g.collapsed?'▾':'▸'}} {{g.name}}</span><small>{{g.rows.length}}</small></button><div v-if="roleSearch||!g.collapsed"><button v-for="r in g.rows" :key="r.key" draggable="true" :data-checklist-role="r.key" :class="{selected:r.key===roleKey,'role-dragging':drag.dragged.value===r.key,'role-drop-before':drag.hovered.value===r.key&&!drag.after.value,'role-drop-after':drag.hovered.value===r.key&&drag.after.value}" @dragstart="drag.start($event,r.key)" @dragend="drag.clear" @dragover="drag.overRole($event,r.key)" @drop="drag.drop($event,g.id,r.key)" title="拖动排序，拖到分组标题可移动分组" @click="roleKey=r.key"><span><strong>{{r.name}}</strong><small>{{r.server||'区服待识别'}}</small></span><em>{{roleProgress(r)}}</em></button></div></section><p v-if="!visibleRoles.length" class="role-empty">{{data.roles.length?'没有匹配的角色':'检测运行窗口后，角色会显示在这里。'}}</p></div></aside>
 <section v-if="role" class="task-panel" :class="{'editing-preferences':settings}"><div class="heading"><div class="role-title"><h2>{{role.name}}</h2><span>{{role.server}}</span><button class="preferences-toggle" :aria-pressed="settings" @click="settings=!settings">{{settings?'完成设置':'任务设置'}}</button></div><div v-if="settings" class="setting-actions"><button @click="snapshotsOpen=true">任务快照</button><button @click="toggleAll(true)">本类全开</button><button @click="toggleAll(false)">本类全关</button></div><label v-else><input type="checkbox" :checked="filter==='pending'" @change="filter=$event.target.checked?'pending':'all'"> 只看未完成</label></div>
 <p v-if="settings" class="preference-note">仅设置当前角色。重要任务优先展示；不提醒的任务保留记录，不计入待办与完成率。待领取统一不催领。</p>
 <div class="completion"><span><b>{{done}}</b> / {{monitored.length}} 已完成</span><div class="progress-track" role="progressbar" aria-label="清单完成进度" :aria-valuenow="done" :aria-valuemin="0" :aria-valuemax="monitored.length||1"><i :style="{width:(monitored.length?done/monitored.length*100:0)+'%'}"></i></div><span v-for="s in summary" :key="s.label" :class="s.tone">{{s.count}} {{s.label}}</span></div>
 <div class="list-columns" aria-hidden="true"><span>任务</span><span>当前进度</span><span>{{settings?'重要程度 / 监控':'状态'}}</span></div>
 <div class="task-list" ref="taskScroller"><section v-for="group in groups" :key="group.name" class="task-group"><h3>{{group.name}}<span>{{group.items.length}} 项</span></h3><div v-for="t in group.items" :key="t.id" class="task-row" :class="[t.status,{disabled:!t.enabled}]" :data-task-id="t.id"><div class="task-name"><span class="state-mark" aria-hidden="true">{{isDone(t)?'✓':t.monitor?'◷':t.status==='claimable'?'!':''}}</span><strong>{{t.name}}</strong><small v-if="!settings&&t.priority==='important'" class="priority-tag important">重要</small><small v-if="!settings&&t.priority==='muted'" class="priority-tag">不提醒</small><small v-if="t.source==='manual'" class="manual-tag">手动</small></div><div class="task-detail" :title="sourceTip(t)"><div v-if="!(t.id==='d1'&&t.parts?.length)" :class="{'storage-progress-inline':t.storage?.remaining>0}"><span>{{t.detail.replace(/ · (?:货币充足，可直接换完|可直接换完，无需刷取)/g,'')}}</span><small v-if="t.storage?.remaining>0" class="stored-reward-note" title="上周储存奖励，本周内有效"> · 上周存余 {{t.storage.remaining}} 次</small></div><div v-if="t.parts?.length" class="prayer-inline"><span v-if="t.id==='d1'&&prayerName(t)" class="prayer-name">{{prayerName(t)}}</span><div class="prayer-parts"><span v-for="part in t.parts" :key="part.name" :title="part.detail"><b>{{part.name}}</b><span :class="part.status">{{typeof part.current==='number'&&typeof part.target==='number'?part.current+'/'+part.target:part.status==='todo'?'未发起':labels[part.status]}}</span></span></div></div><small v-if="t.lifetime" class="lifetime-note">累计福利，不按周重置</small></div><div class="row-status"><div v-if="settings" class="task-preferences"><select :aria-label="t.name+'重要程度'" :value="t.priority||'normal'" @change="change(t,{priority:$event.target.value})"><option value="important">重要</option><option value="normal">普通</option><option value="muted">不提醒</option></select><input type="checkbox" :aria-label="'监控 '+t.name" :checked="t.enabled" @change="change(t,{enabled:$event.target.checked})"></div><span v-else-if="t.monitor||t.available===false" class="status-label" :title="sourceTip(t)">{{labels[t.status]}}</span><select v-else class="status-select" :aria-label="'修改 '+t.name+'状态'" :title="sourceTip(t)+' · 可手动修改，下次检测以游戏数据为准'" :value="t.status" @change="change(t,{status:$event.target.value})"><option v-for="key in manualStates" :key="key" :value="key">{{t.id==='d1'&&key==='active'?'祈愿中':labels[key]}}</option></select></div></div></section></div>
 <p v-if="!groups.length" class="empty">{{settings?'本类暂无任务':tasks.length?'当前筛选下没有任务':'本类监控已全部关闭，可进入监控设置重新开启。'}}</p>
 </section><section v-else class="no-role">读取游戏窗口，开始查看角色清单。</section></div>
 <footer v-if="period!=='overview'">关闭监控或设为不提醒的任务不计入完成率，待领取不催领；寄养与结界卡单独计时。日期按北京时间切换；读取失败保留上次记录，缺少有效数据标为未知。</footer>
</div>
</template>
<style scoped>
